<?php
require_once __DIR__.'/includes/config.php';
require_once __DIR__.'/includes/helpers.php';
$page = $_GET['page'] ?? 'home';

// Ensure a usable first administrator exists. Default: admin@skillconnect.org / admin123
$adminCount = (int)$pdo->query("SELECT COUNT(*) FROM admins")->fetchColumn();
if ($adminCount === 0) {
    $pdo->prepare("INSERT INTO admins(name,email,password_hash) VALUES(?,?,?)")
        ->execute(['System Administrator','admin@skillconnect.org',password_hash('admin123',PASSWORD_DEFAULT)]);
}

if ($page === 'logout') {
    $_SESSION = []; if (ini_get('session.use_cookies')) { $p=session_get_cookie_params(); setcookie(session_name(),'',time()-42000,$p['path'],$p['domain'],$p['secure'],$p['httponly']); } session_destroy(); redirect('index.php');
}

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    csrf_verify();
    if ($page === 'login') {
        $email=post_string('email',190); $password=(string)($_POST['password']??'');
        $stmt=$pdo->prepare("SELECT * FROM admins WHERE email=? LIMIT 1"); $stmt->execute([$email]); $admin=$stmt->fetch();
        if ($admin && password_verify($password,$admin['password_hash'])) {
            session_regenerate_id(true); $_SESSION['admin_id']=$admin['id']; $_SESSION['admin_name']=$admin['name']; redirect('index.php?page=admin');
        }
        flash('error','Invalid email or password.'); redirect('index.php?page=login');
    }

    if ($page === 'register') {
        $name=post_string('full_name',120); $age=(int)($_POST['age']??0); $gender=post_string('gender',30);
        $phone=post_string('phone',30); $email=strtolower(post_string('email',190)); $address=post_string('address',255); $workshopId=(int)($_POST['workshop_id']??0);
        $allowed=['Female','Male','Other','Prefer not to say'];
        if ($name==='' || $age<10 || $age>100 || !in_array($gender,$allowed,true) || !preg_match('/^[0-9+() -]{7,30}$/',$phone) || !filter_var($email,FILTER_VALIDATE_EMAIL) || $address==='' || !$workshopId) {
            flash('error','Please complete every field with valid details.'); redirect('index.php?page=register&workshop='.$workshopId);
        }
        try {
            $pdo->beginTransaction();
            $work=$pdo->prepare("SELECT capacity,(SELECT COUNT(*) FROM registrations r WHERE r.workshop_id=w.id) used FROM workshops w WHERE w.id=? AND w.status='open' FOR UPDATE");
            $work->execute([$workshopId]); $w=$work->fetch();
            if (!$w) throw new Exception('This workshop is unavailable.');
            if ((int)$w['used'] >= (int)$w['capacity']) throw new Exception('This workshop is full.');
            $p=$pdo->prepare("SELECT id FROM participants WHERE email=? LIMIT 1"); $p->execute([$email]); $participant=$p->fetch();
            if ($participant) { $participantId=(int)$participant['id'];
                $u=$pdo->prepare("UPDATE participants SET full_name=?,age=?,gender=?,phone=?,address=? WHERE id=?"); $u->execute([$name,$age,$gender,$phone,$address,$participantId]);
            } else { $p=$pdo->prepare("INSERT INTO participants(full_name,age,gender,phone,email,address) VALUES(?,?,?,?,?,?)"); $p->execute([$name,$age,$gender,$phone,$email,$address]); $participantId=(int)$pdo->lastInsertId(); }
            $r=$pdo->prepare("INSERT INTO registrations(participant_id,workshop_id) VALUES(?,?)"); $r->execute([$participantId,$workshopId]);
            $pdo->commit(); flash('success','Registration confirmed! We look forward to seeing you.'); redirect('index.php?page=workshops');
        } catch (PDOException $e) { if($pdo->inTransaction())$pdo->rollBack(); flash('error',str_starts_with($e->getMessage(),'SQLSTATE[23000]')?'This email is already registered for the selected workshop.':'Could not save the registration.'); redirect('index.php?page=register&workshop='.$workshopId); }
          catch (Exception $e) { if($pdo->inTransaction())$pdo->rollBack(); flash('error',$e->getMessage()); redirect('index.php?page=register&workshop='.$workshopId); }
    }

    admin_required();
    if ($page === 'workshop_save') {
        $id=(int)($_POST['id']??0); $vals=[post_string('name',150),post_string('category',80),post_string('description',5000),post_string('duration',80),$_POST['workshop_date']??'',$_POST['start_time']??'',(int)($_POST['capacity']??0),post_string('location',150),$_POST['status']??'open'];
        if (!$vals[0] || !preg_match('/^\d{4}-\d{2}-\d{2}$/',$vals[4]) || (int)$vals[6]<1) { flash('error','Complete all workshop fields.'); redirect('index.php?page=workshops_admin'); }
        if ($id) {$sql="UPDATE workshops SET name=?,category=?,description=?,duration=?,workshop_date=?,start_time=?,capacity=?,location=?,status=? WHERE id=?";$vals[]=$id;$pdo->prepare($sql)->execute($vals);$workshopId=$id;} else {$pdo->prepare("INSERT INTO workshops(name,category,description,duration,workshop_date,start_time,capacity,location,status) VALUES(?,?,?,?,?,?,?,?,?)")->execute($vals);$workshopId=(int)$pdo->lastInsertId();}
        $session=$pdo->prepare("INSERT IGNORE INTO workshop_sessions(workshop_id,session_date,start_time,qr_token) VALUES(?,?,?,?)");$session->execute([$workshopId,$vals[4],$vals[5],bin2hex(random_bytes(32))); 
        flash('success','Workshop saved successfully.'); redirect('index.php?page=workshops_admin');
    }
    if ($page === 'workshop_delete') { $id=(int)($_POST['id']??0); $pdo->prepare("DELETE FROM workshops WHERE id=?")->execute([$id]); flash('success','Workshop deleted.'); redirect('index.php?page=workshops_admin'); }
    if ($page === 'issue_certificate') { $participantId=(int)($_POST['participant_id']??0); $workshopId=(int)($_POST['workshop_id']??0); $eligible=$pdo->prepare("SELECT COUNT(*) FROM attendance a JOIN registrations r ON r.id=a.registration_id JOIN workshop_sessions s ON s.id=a.session_id WHERE r.participant_id=? AND r.workshop_id=? AND s.workshop_id=? AND a.status='present'"); $eligible->execute([$participantId,$workshopId,$workshopId]); if((int)$eligible->fetchColumn()===0){flash('error','No present attendance found for this participant.');redirect('index.php?page=admin');} $code='SC-'.strtoupper(substr(hash('sha256',$participantId.'-'.$workshopId.'-'.random_bytes(16)),0,12)); try{$pdo->prepare("INSERT IGNORE INTO certificates(participant_id,workshop_id,certificate_code) VALUES(?,?,?)")->execute([$participantId,$workshopId,$code]);flash('success','Certificate issued. Code: '.$code);}catch(PDOException $e){flash('error','Certificate could not be issued.');}redirect('index.php?page=admin'); }
    if ($page === 'attendance') {
        $sessionId=(int)($_POST['session_id']??0); $statuses=$_POST['status']??[];
        foreach($statuses as $registrationId=>$status) { $status=$status==='present'?'present':'absent'; $stmt=$pdo->prepare("INSERT INTO attendance(registration_id,session_id,status,marked_by) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status),marked_by=VALUES(marked_by),marked_at=CURRENT_TIMESTAMP"); $stmt->execute([(int)$registrationId,$sessionId,$status,$_SESSION['admin_id']]); }
        flash('success','Attendance has been saved.'); redirect('index.php?page=attendance&session='.$sessionId);
    }
    if ($page === 'feedback') {
        // Handled by public route below; intentionally not admin
    }
}

