if ($page === 'attendance') {
    admin_required();$sessions=$pdo->query("SELECT s.*,w.name FROM workshop_sessions s JOIN workshops w ON w.id=s.workshop_id ORDER BY s.session_date DESC")->fetchAll();$sessionId=(int)($_GET['session']??($sessions[0]['id']??0));$session=null;$rows=[];$qrUrl='';if($sessionId){$st=$pdo->prepare("SELECT s.*,w.name FROM workshop_sessions s JOIN workshops w ON w.id=s.workshop_id WHERE s.id=?");$st->execute([$sessionId]);$session=$st->fetch();$rt=$pdo->prepare("SELECT r.id,p.full_name,p.email,a.status FROM registrations r JOIN participants p ON p.id=r.participant_id LEFT JOIN attendance a ON a.registration_id=r.id AND a.session_id=? WHERE r.workshop_id=? ORDER BY p.full_name");$rt->execute([$sessionId,(int)$session['workshop_id']]);$rows=$rt->fetchAll();$scheme='http';if(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')$scheme='https';$host=$_SERVER['HTTP_HOST']??'localhost';$qrUrl=$scheme.'://'.$host.'/index.php?page=qr&token='.urlencode($session['qr_token']);}
    $pageTitle='Attendance · SkillConnect';include __DIR__.'/includes/header.php';?><section class="section"><div class="container"><div class="section-heading"><div><span class="eyebrow">Administration</span><h1>Attendance tracker</h1></div></div><form class="filters"><input type="hidden" name="page" value="attendance"><select name="session"><?php foreach($sessions as$s):?><option value="<?=$s['id']?>" <?=($sessionId==$s['id']?'selected':'')?>><?=e($s['name'])?> — <?=date('M j, Y',strtotime($s['session_date']))?></option><?php endforeach;?></select><button class="btn secondary">Open session</button></form><?php if($session):?><div class="admin-grid"><form class="panel" method="post" action="index.php?page=attendance"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="session_id" value="<?= (int)$sessionId?>"><h2><?=e($session['name'])?></h2><div class="table-wrap"><table><thead><tr><th>Participant</th><th>Present</th><th>Absent</th></tr></thead><tbody><?php foreach($rows as$r):?><tr><td><strong><?=e($r['full_name'])?></strong><small><?=e($r['email'])?></small></td><td><input type="radio" name="status[<?= (int)$r['id']?>]" value="present" <?=($r['status']==='present'?'checked':'')?>></td><td><input type="radio" name="status[<?= (int)$r['id']?>]" value="absent" <?=($r['status']==='absent'?'checked':'')?>></td></tr><?php endforeach;?></tbody></table></div><button class="btn primary full">Save attendance</button></form><div class="panel qr-panel"><h2>Session QR</h2><img alt="Workshop attendance QR code" src="https://api.qrserver.com/v1/create-qr-code/?size=220x220&amp;data=<?=urlencode($qrUrl)?>"><p class="muted">Participants scan this code and verify with their registration email.</p></div></div><?php else:?><div class="empty">No workshop sessions are configured.</div><?php endif;?></div></section><?php include __DIR__.'/includes/footer.php';exit;}

if ($page === 'certificate') { $code=$_GET['code']??''; $cert=null;if($code){$st=$pdo->prepare("SELECT c.*,p.full_name,w.name workshop_name FROM certificates c JOIN participants p ON p.id=c.participant_id JOIN workshops w ON w.id=c.workshop_id WHERE c.certificate_code=?");$st->execute([$code]);$cert=$st->fetch();}$pageTitle='Certificate · SkillConnect';include __DIR__.'/includes/header.php';?><section class="section"><div class="container narrow"><?php if($cert):?><div class="certificate" id="certificate"><span class="eyebrow">SkillConnect Community</span><h1>Certificate of Completion</h1><p>This is to certify that</p><h2><?=e($cert['full_name'])?></h2><p>has successfully completed</p><h3><?=e($cert['workshop_name'])?></h3><p>Issued <?=date('F j, Y',strtotime($cert['issued_at']))?> · <?=e($cert['certificate_code'])?></p></div><button class="btn primary full" onclick="window.print()">Download / Print PDF</button><?php else:?><div class="form-card"><h1>Certificate verification</h1><form><input type="hidden" name="page" value="certificate"><label>Certificate code<input name="code" required></label><button class="btn primary full">Verify</button></form></div><?php endif;?></div></section><?php include __DIR__.'/includes/footer.php';exit;}

if ($page === 'reports') {admin_required();if(($_GET['export']??'')==='csv'){header('Content-Type:text/csv');header('Content-Disposition:attachment; filename="skillconnect-report.csv"');$out=fopen('php://output','w');fputcsv($out,['Participant','Email','Workshop','Status','Registered']);$rows=$pdo->query("SELECT p.full_name,p.email,w.name,r.registered_at,COALESCE((SELECT a.status FROM attendance a JOIN workshop_sessions s ON s.id=a.session_id WHERE a.registration_id=r.id ORDER BY s.session_date DESC LIMIT 1),'not marked') status FROM registrations r JOIN participants p ON p.id=r.participant_id JOIN workshops w ON w.id=r.workshop_id")->fetchAll();foreach($rows as$r)fputcsv($out,$r);exit;}$rows=$pdo->query("SELECT p.full_name,p.email,w.name,r.registered_at FROM registrations r JOIN participants p ON p.id=r.participant_id JOIN workshops w ON w.id=r.workshop_id ORDER BY r.registered_at DESC")->fetchAll();$pageTitle='Reports · SkillConnect';include __DIR__.'/includes/header.php';?><section class="section"><div class="container"><div class="section-heading"><div><span class="eyebrow">Administration</span><h1>Reports</h1></div><div class="hero-actions"><button class="btn tertiary" type="button" onclick="window.print()">Print / Save PDF</button><a class="btn primary" href="index.php?page=reports&export=csv">Export Excel CSV</a></div></div><div class="panel table-wrap"><table><thead><tr><th>Participant</th><th>Email</th><th>Workshop</th><th>Registered</th></tr></thead><tbody><?php foreach($rows as$r):?><tr><td><?=e($r['full_name'])?></td><td><?=e($r['email'])?></td><td><?=e($r['name'])?></td><td><?=date('M j, Y',strtotime($r['registered_at']))?></td></tr><?php endforeach;?></tbody></table></div></div></section><?php include __DIR__.'/includes/footer.php';exit;}

if ($page === 'certificates_admin') { admin_required(); $participants=$pdo->query("SELECT id,full_name FROM participants ORDER BY full_name")->fetchAll();$workshops=$pdo->query("SELECT id,name FROM workshops ORDER BY name")->fetchAll();$issued=$pdo->query("SELECT c.*,p.full_name,w.name workshop_name FROM certificates c JOIN participants p ON p.id=c.participant_id JOIN workshops w ON w.id=c.workshop_id ORDER BY c.issued_at DESC")->fetchAll();$pageTitle='Certificates · SkillConnect';include __DIR__.'/includes/header.php';?><section class="section"><div class="container split"><div class="form-card"><span class="eyebrow">Administration</span><h1>Issue certificate</h1><form method="post" action="index.php?page=issue_certificate"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><label>Participant<select name="participant_id" required><option value="">Select participant</option><?php foreach($participants as$p):?><option value="<?=$p['id']?>"><?=e($p['full_name'])?></option><?php endforeach;?></select></label><label>Workshop<select name="workshop_id" required><?php foreach($workshops as$w):?><option value="<?=$w['id']?>"><?=e($w['name'])?></option><?php endforeach;?></select></label><button class="btn primary full">Issue certificate</button></form></div><div class="panel"><h2>Issued certificates</h2><?php foreach($issued as$c):?><div class="feedback"><strong><?=e($c['full_name'])?></strong><p><?=e($c['workshop_name'])?><br><a class="text-link" href="index.php?page=certificate&code=<?=urlencode($c['certificate_code'])?>"><?=e($c['certificate_code'])?></a></p></div><?php endforeach;if(!$issued):?><p class="muted">No certificates issued yet.</p><?php endif;?></div></div></section><?php include __DIR__.'/includes/footer.php';exit;}

